const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');

const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://env.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

const url = scalekit.getAuthorizationUrl(
  'http://localhost:3001/callback',
  {
    organizationId: 'org_1234567890',
    state: 'random_state_string'
  }
);

fs.writeFileSync('/home/user/scalekit-auth-url/output.log', url);

